// fixed fixtures generated by php 8.4 (512-bit RSA pair + self-signed cert)
$priv = base64_decode("");
$pub = base64_decode("LS0tLS1CRUdJTiBQVUJMSUMgS0VZLS0tLS0KTUZ3d0RRWUpLb1pJaHZjTkFRRUJCUUFEU3dBd1NBSkJBTWlxaktJK1VMZkdsNUxGcTQvdE93Z0NVNloxMDRBYQp5Z01jRTltS1p1Tng4MmxYOHRDakFJTTdZSlZXOFBhbWJneXpOZDdmYS96NUlHZFdocnBvbGxjQ0F3RUFBUT09Ci0tLS0tRU5EIFBVQkxJQyBLRVktLS0tLQo=");
$sig = base64_decode("Wo6VfTyd6ZpMTJ/+42YjnQ01mYsO6N4pyJbgKSc0pUNmKI3DoPghNklnmE+DK/tFyGwbkIc8f4WLxYJA79sGhA==");
$cert = base64_decode("");

// digests
var_dump(openssl_digest("abc", "sha256"), openssl_digest("abc", "md5"));

// symmetric ciphers (byte-level)
$e = openssl_encrypt("secret", "aes-128-cbc", "0123456789abcdef", OPENSSL_RAW_DATA, "1111111111111111");
var_dump(bin2hex($e));
var_dump(openssl_decrypt($e, "aes-128-cbc", "0123456789abcdef", OPENSSL_RAW_DATA, "1111111111111111"));
var_dump(bin2hex(openssl_encrypt("secret", "aes-128-cbc", "0123456789abcdef", 0, "1111111111111111")));
$c = openssl_encrypt("data", "aes-256-ctr", str_repeat("k", 32), OPENSSL_RAW_DATA, str_repeat("i", 16));
var_dump(bin2hex($c));
var_dump(openssl_cipher_iv_length("aes-128-cbc"), openssl_cipher_iv_length("nope"));
var_dump(in_array("aes-256-gcm", openssl_get_cipher_methods()));

// RSA sign/verify (fixtures fixed → deterministic)
openssl_sign("hello", $s2, $priv, OPENSSL_ALGO_SHA256);
var_dump($s2 === $sig, openssl_verify("hello", $sig, $pub, OPENSSL_ALGO_SHA256), openssl_verify("tamper", $sig, $pub, OPENSSL_ALGO_SHA256));
openssl_sign("hello", $s3, $priv, OPENSSL_ALGO_SHA1);
var_dump(strlen($s3), openssl_verify("hello", $s3, $pub, OPENSSL_ALGO_SHA1));

// pkey details
$k = openssl_pkey_get_private($priv);
$d = openssl_pkey_get_details($k);
var_dump($d["bits"], bin2hex($d["rsa"]["n"]), bin2hex($d["rsa"]["e"]));

// RSA encrypt pairs
openssl_public_encrypt("abc", $ct, $pub);
var_dump(strlen($ct));
var_dump(openssl_private_decrypt($ct, $pt, $priv), $pt);
openssl_private_encrypt("xy", $ct2, $priv);
var_dump(openssl_public_decrypt($ct2, $pt2, $pub), $pt2);

// X509
$p = openssl_x509_parse($cert);
var_dump($p["subject"]["CN"], $p["subject"]["emailAddress"], $p["validFrom"], $p["name"]);
$co = openssl_x509_read($cert);
var_dump(strlen(openssl_x509_fingerprint($co)), openssl_x509_verify($co, $co), openssl_x509_check_private_key($co, $priv));
